<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { api, type Paginated } from '../lib/api';
import AppShell from './AppShell.vue';

type Row = Record<string, any> & { id?: number };
type Field = { key: string; label: string; type?: string; required?: boolean; options?: readonly string[] };
type ResourceName = 'buildings' | 'roomTypes' | 'rooms' | 'tenants' | 'contracts' | 'invoices' | 'payments' | 'utilityMeters' | 'meterReadings' | 'expenses';
const props = defineProps<{ title: string; description: string; resource: ResourceName; columns: readonly { key: string; label: string }[]; fields: readonly Field[] }>();
const rows = ref<Row[]>([]); const loading = ref(true); const saving = ref(false); const modal = ref(false); const editing = ref<Row | null>(null); const search = ref(''); const error = ref(''); const success = ref(''); const page = ref(1); const lastPage = ref(1); const total = ref(0); const form = reactive<Record<string, any>>({});
const resourceApi = () => api[props.resource] as typeof api.rooms;
const value = (row: Row, key: string) => { const result = key.split('.').reduce((current, part) => current?.[part], row as any); return result === undefined || result === null || result === '' ? '—' : result; };
const load = async () => { loading.value = true; error.value = ''; try { const response = await resourceApi().list({ page: page.value, per_page: 10, search: search.value }); const result = response.data as Paginated<Row>; rows.value = result.data; lastPage.value = result.last_page; total.value = result.total; } catch (e) { error.value = e instanceof Error ? e.message : 'Unable to load records.'; } finally { loading.value = false; } };
const open = (row?: Row) => { editing.value = row ?? null; Object.keys(form).forEach((key) => delete form[key]); props.fields.forEach((field) => { form[field.key] = row?.[field.key] ?? field.options?.[0] ?? (field.type === 'checkbox' ? true : ''); }); modal.value = true; };
const save = async () => { saving.value = true; error.value = ''; try { if (editing.value?.id) await resourceApi().update(editing.value.id, form); else await resourceApi().create(form); modal.value = false; success.value = 'Record saved successfully.'; await load(); } catch (e) { error.value = e instanceof Error ? e.message : 'Unable to save record.'; } finally { saving.value = false; } };
const remove = async (row: Row) => { if (!row.id || !window.confirm('Delete this record?')) return; try { await resourceApi().remove(row.id); success.value = 'Record deleted.'; await load(); } catch (e) { error.value = e instanceof Error ? e.message : 'Unable to delete record.'; } };
onMounted(load);
</script>

<template>
    <AppShell :title="title">
        <section class="mx-auto max-w-7xl space-y-6 p-5 sm:p-8">
            <div class="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="text-xs font-bold uppercase tracking-widest text-teal-700">RENTAL OPERATIONS</p><h1 class="mt-2 text-3xl font-bold tracking-tight text-slate-800">{{ title }}</h1><p class="mt-1 text-sm text-slate-500">{{ description }}</p></div><button class="rounded-lg bg-teal-700 px-4 py-2.5 text-sm font-semibold text-white shadow-sm hover:bg-teal-800" @click="open()">＋ Add record</button></div>
            <p v-if="error" class="rounded-lg bg-red-50 p-3 text-sm text-red-700">{{ error }}</p><p v-if="success" class="rounded-lg bg-emerald-50 p-3 text-sm text-emerald-700">{{ success }}</p>
            <div class="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><div class="flex flex-col gap-3 border-b border-slate-100 p-4 sm:flex-row"><div class="flex-1"><h2 class="font-semibold text-slate-700">{{ total }} records</h2></div><input v-model="search" class="rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-teal-600" placeholder="Search records..." @keyup.enter="load" /><button class="rounded-lg border border-slate-200 px-4 text-sm text-slate-600 hover:bg-slate-50" @click="load">Search</button></div><div class="overflow-x-auto"><table class="w-full min-w-[680px] text-left text-sm"><thead class="bg-slate-50 text-[11px] uppercase tracking-wide text-slate-400"><tr><th v-for="column in columns" :key="column.key" class="px-4 py-3 font-semibold">{{ column.label }}</th><th class="px-4 py-3">Actions</th></tr></thead><tbody><tr v-if="loading"><td :colspan="columns.length + 1" class="px-4 py-14 text-center text-slate-400">Loading records...</td></tr><tr v-else-if="!rows.length"><td :colspan="columns.length + 1" class="px-4 py-14 text-center text-slate-400">No records found.</td></tr><tr v-for="row in rows" v-else :key="row.id" class="border-t border-slate-100 hover:bg-slate-50/60"><td v-for="column in columns" :key="column.key" class="px-4 py-3 text-slate-600">{{ value(row, column.key) }}</td><td class="whitespace-nowrap px-4 py-3"><button class="mr-3 text-teal-700 hover:underline" @click="open(row)">Edit</button><button class="text-red-600 hover:underline" @click="remove(row)">Delete</button></td></tr></tbody></table></div><div class="flex items-center justify-end gap-4 border-t border-slate-100 p-4 text-xs text-slate-500"><button class="rounded border px-3 py-1.5 disabled:opacity-40" :disabled="page <= 1" @click="page--; load()">Previous</button><span>Page {{ page }} of {{ lastPage }}</span><button class="rounded border px-3 py-1.5 disabled:opacity-40" :disabled="page >= lastPage" @click="page++; load()">Next</button></div></div>
        </section>
        <div v-if="modal" class="fixed inset-0 z-50 grid place-items-center bg-slate-900/40 p-4" @click.self="modal = false"><form class="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-xl bg-white p-6 shadow-2xl" @submit.prevent="save"><div class="mb-6 flex justify-between"><div><p class="text-xs font-bold uppercase tracking-widest text-teal-700">{{ editing ? 'EDIT RECORD' : 'NEW RECORD' }}</p><h2 class="mt-1 text-xl font-bold text-slate-800">{{ editing ? 'Edit' : 'Add' }} {{ title }}</h2></div><button type="button" class="text-2xl text-slate-400" @click="modal = false">×</button></div><div class="grid gap-4 sm:grid-cols-2"><label v-for="field in fields" :key="field.key" class="text-xs font-semibold text-slate-600">{{ field.label }}<select v-if="field.options" v-model="form[field.key]" class="mt-1.5 w-full rounded-lg border border-slate-200 p-2.5 text-sm" :required="field.required"><option v-for="option in field.options" :key="option">{{ option }}</option></select><textarea v-else-if="field.type === 'textarea'" v-model="form[field.key]" class="mt-1.5 w-full rounded-lg border border-slate-200 p-2.5 text-sm" :required="field.required" /><input v-else v-model="form[field.key]" class="mt-1.5 w-full rounded-lg border border-slate-200 p-2.5 text-sm" :type="field.type === 'checkbox' ? 'checkbox' : field.type ?? 'text'" :required="field.required" /></label></div><div class="mt-6 flex justify-end gap-3"><button type="button" class="rounded-lg border px-4 py-2 text-sm" @click="modal = false">Cancel</button><button class="rounded-lg bg-teal-700 px-4 py-2 text-sm font-semibold text-white" :disabled="saving">{{ saving ? 'Saving...' : 'Save record' }}</button></div></form></div>
    </AppShell>
</template>
